package containerd

import "testing"

// TestResolvConfHasNameserver_RealWorldBrokenFiles uses the exact contents seen
// on hosts where this actually went wrong. Both look like a populated,
// readable config and name no resolver.
func TestResolvConfHasNameserver_RealWorldBrokenFiles(t *testing.T) {
	// systemd-resolved before it has learned an upstream. Observed verbatim on a
	// dev container that could not reach github.com while its host could.
	resolvedNoUpstream := `# This is /run/systemd/resolve/stub-resolv.conf managed by man:systemd-resolved(8).
# Do not edit.
#
# Third party programs should typically not access this file directly, but only
# through the symlink at /etc/resolv.conf.

# No DNS servers known.
search .
`
	if resolvConfHasNameserver(resolvedNoUpstream) {
		t.Error("a resolved stub with no upstream must not count as configured")
	}

	// NetworkManager before DHCP completes.
	if resolvConfHasNameserver("# Generated by NetworkManager\nsearch localdomain\n") {
		t.Error("search-only config must not count as configured")
	}

	if resolvConfHasNameserver("") {
		t.Error("an empty file must not count as configured")
	}
}

// A nameserver line with no value is not a resolver.
func TestResolvConfHasNameserver_RejectsValuelessDirective(t *testing.T) {
	if resolvConfHasNameserver("nameserver\n") {
		t.Error("a bare 'nameserver' with no address must not count")
	}
	if resolvConfHasNameserver("nameserver   \n") {
		t.Error("'nameserver' with only whitespace must not count")
	}
}

// A commented-out nameserver is not a resolver either -- this is what a
// hand-edited file often looks like mid-debugging.
func TestResolvConfHasNameserver_IgnoresComments(t *testing.T) {
	if resolvConfHasNameserver("# nameserver 8.8.8.8\n; nameserver 1.1.1.1\n") {
		t.Error("commented nameservers must not count as configured")
	}
}

func TestResolvConfHasNameserver_AcceptsWorkingConfigs(t *testing.T) {
	for name, in := range map[string]string{
		"plain":           "nameserver 192.168.0.1\n",
		"with search":     "search localdomain\nnameserver 192.168.0.1\n",
		"tab separated":   "nameserver\t192.168.0.1\n",
		"leading space":   "   nameserver 192.168.0.1\n",
		"resolved stub":   "nameserver 127.0.0.53\noptions edns0 trust-ad\n",
		"ipv6":            "nameserver fd00::1\n",
		"after a comment": "# managed by NetworkManager\nnameserver 10.0.0.1\n",
		"mixed case":      "Nameserver 10.0.0.1\n",
	} {
		if !resolvConfHasNameserver(in) {
			t.Errorf("%s: want configured, got not configured for %q", name, in)
		}
	}
}
